// Currency data replicating the observable behaviour of the Python `moneyed`
// package combined with Babel's `en_US` locale formatting:
//   - supported ISO 4217 codes (unknown codes raise CurrencyDoesNotExist)
//   - fraction digits per currency (as used by Babel's format_currency)
//   - display symbol per currency in the en_US locale
//     (currencies without a dedicated en_US symbol fall back to their code)

// Currencies with 0 fraction digits.
const ZERO_DIGIT = new Set([
  'JPY', 'KRW', 'LBP', 'XOF', 'XAF', 'XPF', 'CLP', 'PYG', 'RSD', 'ALL',
  'AFN', 'IRR', 'IQD', 'SYP', 'YER', 'LAK', 'MMK', 'KPW', 'VUV', 'KMF',
  'MGA', 'RWF', 'BIF', 'DJF', 'SOS', 'UGX', 'GNF', 'SLL', 'MRO', 'STD',
]);

// Currencies with 3 fraction digits.
const THREE_DIGIT = new Set(['KWD', 'BHD', 'OMR', 'JOD', 'TND']);

// All currency codes accepted by moneyed (everything else is rejected).
const SUPPORTED = new Set([
  'USD', 'EUR', 'GBP', 'JPY', 'CNY', 'CAD', 'AUD', 'NZD', 'CHF', 'HKD',
  'SGD', 'INR', 'KRW', 'MXN', 'BRL', 'ZAR', 'RUB', 'SEK', 'NOK', 'DKK',
  'PLN', 'CZK', 'HUF', 'TRY', 'ILS', 'THB', 'PHP', 'IDR', 'MYR', 'VND',
  'TWD', 'AED', 'SAR', 'QAR', 'KWD', 'BHD', 'OMR', 'JOD', 'LBP', 'EGP',
  'NGN', 'KES', 'GHS', 'MAD', 'TND', 'DZD', 'XOF', 'XAF', 'XCD', 'XPF',
  'ARS', 'CLP', 'COP', 'PEN', 'UYU', 'VES', 'BOB', 'PYG', 'CRC', 'PAB',
  'DOP', 'GTQ', 'HNL', 'NIO', 'JMD', 'TTD', 'BBD', 'BSD', 'BZD', 'GYD',
  'SRD', 'AWG', 'ANG', 'CUP', 'HTG', 'KYD', 'FKP', 'GIP', 'SHP', 'BMD',
  'BAM', 'RSD', 'MKD', 'ALL', 'MDL', 'UAH', 'BYN', 'GEL', 'AMD', 'AZN',
  'KZT', 'UZS', 'TJS', 'TMT', 'KGS', 'MNT', 'AFN', 'PKR', 'BDT', 'LKR',
  'NPR', 'BTN', 'MVR', 'IRR', 'IQD', 'SYP', 'YER', 'LAK', 'KHR', 'MMK',
  'KPW', 'MOP', 'BND', 'FJD', 'PGK', 'TOP', 'WST', 'VUV', 'SBD', 'KMF',
  'MGA', 'MUR', 'SCR', 'MWK', 'ZMW', 'MZN', 'BWP', 'NAD', 'LSL', 'SZL',
  'AOA', 'CDF', 'RWF', 'BIF', 'DJF', 'ERN', 'ETB', 'SOS', 'SDG', 'SSP',
  'UGX', 'TZS', 'GMD', 'GNF', 'LRD', 'SLE', 'SLL', 'MRU', 'MRO', 'CVE',
  'STN', 'STD', 'XAU', 'XAG', 'XPD', 'XPT', 'XDR', 'XBA', 'XBB', 'XBC',
  'XBD', 'XTS', 'XXX', 'ZWL', 'ZWR',
]);

// en_US display symbols. Anything not listed here is displayed as its code.
const SYMBOLS = new Map([
  ['USD', '$'],
  ['EUR', '€'],
  ['GBP', '£'],
  ['JPY', '¥'],
  ['CNY', 'CN¥'],
  ['CAD', 'CA$'],
  ['AUD', 'A$'],
  ['NZD', 'NZ$'],
  ['HKD', 'HK$'],
  ['INR', '₹'],
  ['KRW', '₩'],
  ['MXN', 'MX$'],
  ['BRL', 'R$'],
  ['ILS', '₪'],
  ['PHP', '₱'],
  ['VND', '₫'],
  ['TWD', 'NT$'],
  ['XCD', 'EC$'],
  ['XPF', 'CFPF'],
  // The space inside the XOF symbol is a narrow no-break space (U+202F).
  ['XOF', 'F CFA'],
  ['XAF', 'FCFA'],
  ['XXX', '¤'],
]);

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
    this.code = code;
  }
}

// Mirror of moneyed.get_currency(): codes are matched case-insensitively.
export function getCurrency(code) {
  const upper = String(code).toUpperCase();
  if (!SUPPORTED.has(upper)) {
    throw new CurrencyDoesNotExist(upper);
  }
  const digits = ZERO_DIGIT.has(upper) ? 0 : THREE_DIGIT.has(upper) ? 3 : 2;
  const symbol = SYMBOLS.has(upper) ? SYMBOLS.get(upper) : upper;
  return { code: upper, digits, symbol };
}

// Decimal string utilities replicating the numeric behaviour of CPython's
// str(float) -> decimal.Decimal -> quantize(ROUND_HALF_EVEN) pipeline and
// Babel's en_US number grouping. No Intl / BigInt is used anywhere.

// Split a finite JS number into its exact shortest decimal representation
// (same digits as Python's repr of the same double): sign, integer digit
// string (no leading zeros except "0" itself) and fraction digit string.
export function numberToDecimalParts(n) {
  const negative = n < 0 || Object.is(n, -0);
  let s = Math.abs(n).toString(); // shortest round-trip digits, maybe "1e+21"

  let mantissa = s;
  let exponent = 0;
  const eIndex = s.indexOf('e');
  if (eIndex !== -1) {
    mantissa = s.slice(0, eIndex);
    exponent = parseInt(s.slice(eIndex + 1), 10);
  }

  let intPart;
  let fracPart;
  const dotIndex = mantissa.indexOf('.');
  if (dotIndex === -1) {
    intPart = mantissa;
    fracPart = '';
  } else {
    intPart = mantissa.slice(0, dotIndex);
    fracPart = mantissa.slice(dotIndex + 1);
  }

  if (exponent !== 0) {
    const digits = intPart + fracPart;
    // Position of the decimal point relative to the start of `digits`.
    const point = intPart.length + exponent;
    if (point <= 0) {
      intPart = '0';
      fracPart = '0'.repeat(-point) + digits;
    } else if (point >= digits.length) {
      intPart = digits + '0'.repeat(point - digits.length);
      fracPart = '';
    } else {
      intPart = digits.slice(0, point);
      fracPart = digits.slice(point);
    }
  }

  // Normalize: strip leading zeros of the integer part, trailing zeros of
  // the fraction part (Decimal('1.50') behaves like Decimal('1.5')).
  intPart = intPart.replace(/^0+(?=\d)/, '');
  fracPart = fracPart.replace(/0+$/, '');

  return { negative, intPart, fracPart };
}

// Increment a digit string in place semantics; returns new digit string and
// whether a carry overflowed the most significant digit.
function incrementDigits(digits) {
  const arr = digits.split('');
  for (let i = arr.length - 1; i >= 0; i -= 1) {
    if (arr[i] !== '9') {
      arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1);
      return { digits: arr.join(''), carry: false };
    }
    arr[i] = '0';
  }
  return { digits: arr.join(''), carry: true };
}

// ROUND_HALF_EVEN rounding of (intPart.fracPart) to `places` fraction digits.
// Returns { intPart, fracPart } with fracPart padded to exactly `places`
// digits.
export function roundHalfEven(intPart, fracPart, places) {
  let kept = fracPart.slice(0, places);
  if (fracPart.length > places) {
    const firstDropped = fracPart.charCodeAt(places) - 48;
    const rest = fracPart.slice(places + 1);
    const restNonZero = /[1-9]/.test(rest);
    let roundUp;
    if (firstDropped > 5) {
      roundUp = true;
    } else if (firstDropped < 5) {
      roundUp = false;
    } else if (restNonZero) {
      roundUp = true;
    } else {
      // Exactly halfway: round to even. With zero kept digits the last kept
      // digit is the units digit of the integer part.
      const lastKept = places > 0
        ? kept.charCodeAt(kept.length - 1) - 48
        : intPart.charCodeAt(intPart.length - 1) - 48;
      roundUp = lastKept % 2 === 1;
    }
    if (roundUp) {
      if (places > 0) {
        const result = incrementDigits(kept);
        kept = result.digits;
        if (result.carry) {
          const intResult = incrementDigits(intPart);
          intPart = intResult.carry ? '1' + intResult.digits : intResult.digits;
          kept = kept.slice(0); // kept stays `places` long after overflow? no:
        }
      } else {
        const intResult = incrementDigits(intPart);
        intPart = intResult.carry ? '1' + intResult.digits : intResult.digits;
      }
    }
  }
  // Pad the fraction to exactly `places` digits.
  while (kept.length < places) {
    kept += '0';
  }
  return { intPart, fracPart: kept };
}

// Babel en_US grouping: ',' between every three integer digits.
export function groupThousands(intPart) {
  return intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

