// Minimal reimplementation of moneyed.Money limited to the behaviour the
// original script exercises: construction, `<` comparison and str().

import { getCurrency } from './currencies.mjs';
import {
  numberToDecimalParts,
  roundHalfEven,
  groupThousands,
} from './decimal.mjs';

// Raised for the same condition as Python's decimal.InvalidOperation when a
// NaN amount takes part in a comparison.
export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.name = 'InvalidOperation';
  }
}

export class Money {
  constructor(amount, currency) {
    // moneyed stores the amount as Decimal(str(amount)); the JS double is
    // the same value, and its decimal digits are recovered at format time.
    this.amount = amount;
    this.currency = getCurrency(currency);
  }

  lt(other) {
    if (Number.isNaN(this.amount) || Number.isNaN(other.amount)) {
      throw new InvalidOperation();
    }
    return this.amount < other.amount;
  }

  toString() {
    const { symbol, digits } = this.currency;
    const amount = this.amount;
    const negative = amount < 0 || Object.is(amount, -0);

    let numberText;
    if (!Number.isFinite(amount)) {
      // Babel formats infinite values as the infinity symbol, no decimals.
      numberText = '∞';
    } else {
      const parts = numberToDecimalParts(amount);
      const rounded = roundHalfEven(parts.intPart, parts.fracPart, digits);
      numberText = groupThousands(rounded.intPart);
      if (digits > 0) {
        numberText += '.' + rounded.fracPart;
      }
    }
    // en_US currency pattern: "¤#,##0.00" with a plain leading minus.
    return (negative ? '-' : '') + symbol + numberText;
  }
}

// Reimplementation of CPython's float(str) parsing for argparse's
// type=float conversion, including its error message shape.

// Python float() accepts surrounding ASCII whitespace, an optional sign,
// decimal digits with single underscores between digits, an optional
// fraction (including a bare trailing dot), an optional exponent, and the
// case-insensitive words "inf", "infinity" and "nan".
const FLOAT_RE = /^[+-]?(?:(?:\d(?:_\d)*)(?:\.(?:\d(?:_\d)*)?)?|\.\d(?:_\d)*)(?:[eE][+-]?\d(?:_\d)*)?$/;
const SPECIAL_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;

export class InvalidFloatValue extends Error {
  constructor(raw) {
    super(`invalid float value: ${pythonRepr(raw)}`);
    this.name = 'InvalidFloatValue';
    this.raw = raw;
  }
}

// Python repr() of a (short, ASCII-ish) string: single quotes by default.
function pythonRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + quote;
}

export function parsePythonFloat(raw) {
  // Python strips leading/trailing whitespace (str.strip() set).
  const s = raw.replace(/^[\t\n\v\f\r ]+|[\t\n\v\f\r ]+$/g, '');
  if (SPECIAL_RE.test(s)) {
    const lower = s.toLowerCase();
    const neg = lower.startsWith('-');
    if (lower.includes('nan')) return NaN;
    return neg ? -Infinity : Infinity;
  }
  if (!FLOAT_RE.test(s)) {
    throw new InvalidFloatValue(raw);
  }
  return Number(s.replace(/_/g, ''));
}

