```js
function formatUsage(prog) {
  const prefix = 'usage: ';
  const textWidth = 78; // (80 columns - 2) when not a tty
  const actionUsages = ['[-h]', '--amount1 AMOUNT1', '--amount2 AMOUNT2', '--currency CURRENCY'];
  const usage = prog + ' ' + actionUsages.join(' ');
  if (prefix.length + usage.length <= textWidth) {
    return prefix + usage + '\n';
  }
  const parts = [prog, ...actionUsages.flatMap(u => u.split(' '))];
  const indent = ' '.repeat(prefix.length + prog.length + 1);
  const lines = [];
  let line = [];
  let lineLen = prefix.length - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length) {
      lines.push(line);
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  lines.push(line);
  return prefix + lines[0].join(' ') + '\n' +
    lines.slice(1).map(l => indent + l.join(' ') + '\n').join('');
}
