const ACTIONS = [
  { optionStrings: ['-h', '--help'], dest: 'help', takesArg: false, required: false },
  { optionStrings: ['--amount1'], dest: 'amount1', takesArg: true, type: 'float', required: true },
  { optionStrings: ['--amount2'], dest: 'amount2', takesArg: true, type: 'float', required: true },
  { optionStrings: ['--currency'], dest: 'currency', takesArg: true, type: 'str', required: true },
];

const ACTION_USAGES = [
  '[-h]',
  '--amount1 AMOUNT1',
  '--amount2 AMOUNT2',
  '--currency CURRENCY',
];

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const ALL_OPTION_STRINGS = ACTIONS.flatMap((a) => a.optionStrings);
const BY_EXACT = new Map();
for (const action of ACTIONS) {
  for (const s of action.optionStrings) {
    BY_EXACT.set(s, action);
  }
}

function actionName(action) {
  return action.optionStrings.join('/');
}

export function formatUsage(prog) {
  const usage = prog + ' ' + ACTION_USAGES.join(' ');
  if (PREFIX.length + usage.length <= TEXT_WIDTH) {
    return PREFIX + usage + '\n';
  }
  // argparse splits the option usages into whitespace-separated tokens
  // (its part_regexp matches \S+ for non-grouped items) and wraps greedily.
  const parts = [prog, ...ACTION_USAGES.flatMap((u) => u.split(' '))];
  const indent = ' '.repeat(PREFIX.length + prog.length + 1);
  const lines = [];
  let line = [];
  let lineLen = PREFIX.length - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > TEXT_WIDTH && line.length > 0) {
      lines.push(line);
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  lines.push(line);
  let out = PREFIX + lines[0].join(' ') + '\n';
  for (const rest of lines.slice(1)) {
    out += indent + rest.join(' ') + '\n';
  }
  return out;
}

export function formatHelp(prog) {
  return (
    formatUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help           show this help message and exit\n' +
    '  --amount1 AMOUNT1\n' +
    '  --amount2 AMOUNT2\n' +
    '  --currency CURRENCY\n'
  );
}

class ParserExit extends Error {
  constructor(code) {
    super(`parser exit ${code}`);
    this.code = code;
  }
}

function fail(prog, message) {
  writeSync(2, formatUsage(prog) + `${prog}: error: ${message}\n`);
  throw new ParserExit(2);
}

// Long-option prefix matching (argparse._get_option_tuples, -- variant).
function matchLongPrefix(name) {
  if (!name.startsWith('--')) return [];
  return ACTIONS.flatMap((action) =>
    action.optionStrings
      .filter((s) => s.startsWith('--') && s.startsWith(name))
      .map((optionString) => ({ action, optionString })),
  );
}

// Mirror of argparse._parse_optional: does this token look like an option
// string (as opposed to a value / positional)?
function looksLikeOption(prog, tok) {
  if (!tok.startsWith('-')) return false;
  if (BY_EXACT.has(tok)) return true;
  if (tok.length === 1) return false; // a bare '-' is a value
  let name = tok;
  const eq = tok.indexOf('=');
  if (eq !== -1) {
    name = tok.slice(0, eq);
    if (BY_EXACT.has(name)) return true;
  }
  const tuples = matchLongPrefix(name);
  if (tuples.length > 1) {
    fail(
      prog,
      `ambiguous option: ${name} could match ${tuples
        .map((t) => t.optionString)
        .join(', ')}`,
    );
  }
  if (tuples.length === 1) return true;
  // It does not match any option: a negative number is a value (this parser
  // has no options that look like negative numbers).
  if (NEGATIVE_NUMBER_RE.test(tok)) return false;
  if (tok.includes(' ')) return false;
  return true; // unknown option string
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];
  let positionalOnly = false;
  let i = 0;

  try {
    while (i < argv.length) {
      const tok = argv[i];
      if (positionalOnly) {
        extras.push(tok);
        i += 1;
        continue;
      }
      if (tok === '--') {
        // First '--': everything after it is positional; the marker itself
        // shows up among the unrecognized arguments (Python 3.13 argparse).
        positionalOnly = true;
        extras.push('--');
        i += 1;
        continue;
      }
      if (looksLikeOption(prog, tok)) {
        let name = tok;
        let explicit;
        const eq = tok.indexOf('=');
        if (tok.startsWith('--') && eq !== -1) {
          name = tok.slice(0, eq);
          explicit = tok.slice(eq + 1);
        }
        let action;
        if (BY_EXACT.has(name)) {
          action = BY_EXACT.get(name);
        } else {
          const tuples = matchLongPrefix(name);
          if (tuples.length > 1) {
            fail(
              prog,
              `ambiguous option: ${name} could match ${tuples
                .map((t) => t.optionString)
                .join(', ')}`,
            );
          }
          if (tuples.length === 1) action = tuples[0].action;
        }
        if (!action) {
          extras.push(tok); // unrecognized optional
          i += 1;
          continue;
        }
        if (!action.takesArg) {
          if (explicit !== undefined) {
            fail(prog, `argument ${actionName(action)}: ignored explicit argument '${explicit}'`);
          }
          writeSync(1, formatHelp(prog));
          throw new ParserExit(0);
        }
        let raw;
        if (explicit !== undefined) {
          raw = explicit;
        } else {
          const next = argv[i + 1];
          if (next === undefined || next === '--' || looksLikeOption(prog, next)) {
            fail(prog, `argument ${actionName(action)}: expected one argument`);
          }
          raw = next;
          i += 1;
        }
        if (action.type === 'float') {
          try {
            values[action.dest] = parsePythonFloat(raw);
          } catch (e) {
            fail(prog, `argument ${actionName(action)}: ${e.message}`);
          }
        } else {
          values[action.dest] = raw;
        }
        i += 1;
      } else {
        extras.push(tok); // positional, but this parser defines none
        i += 1;
      }
    }

    const missing = ACTIONS.filter((a) => a.required && !(a.dest in values));
    if (missing.length > 0) {
      fail(
        prog,
        `the following arguments are required: ${missing
          .map(actionName)
          .join(', ')}`,
      );
    }
    if (extras.length > 0) {
      fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
    }
  } catch (e) {
    if (e instanceof ParserExit) {
      process.exitCode = e.code;
      return null;
    }
    throw e;
  }
  return values;
}

// Entry point — JS port of /workspace/dataset/test19.py
//
//   import argparse
//   from moneyed import Money
//   ...
//   if m1 < m2: smaller = m1
//   else:       smaller = m2
//   print(smaller)

import { basename } from 'node:path';
import { writeSync } from 'node:fs';
import { parseArgs } from './argparse.mjs';
import { Money, InvalidOperation } from './money.mjs';
import { CurrencyDoesNotExist } from './currencies.mjs';

const prog = basename(process.argv[1] || 'test19.mjs');

const args = parseArgs(process.argv.slice(2), prog);
if (args === null) {
  // Help was shown (exit 0) or a parse error was reported (exit 2).
} else {
  let m1;
  let m2;
  try {
    m1 = new Money(args.amount1, args.currency);
    m2 = new Money(args.amount2, args.currency);
  } catch (e) {
    if (e instanceof CurrencyDoesNotExist) {
      // moneyed.classes.CurrencyDoesNotExist -> traceback, exit code 1
      writeSync(2, `moneyed.classes.CurrencyDoesNotExist: ${e.message}\n`);
      process.exitCode = 1;
    } else {
      throw e;
    }
  }

  if (m1 !== undefined) {
    let smaller;
    try {
      smaller = m1.lt(m2) ? m1 : m2;
    } catch (e) {
      if (e instanceof InvalidOperation) {
        // decimal.InvalidOperation on NaN comparison -> traceback, exit 1
        writeSync(2, `decimal.InvalidOperation: ${e.message}\n`);
        process.exitCode = 1;
      } else {
        throw e;
      }
    }
    if (smaller !== undefined) {
      writeSync(1, smaller.toString() + '\n');
    }
  }
}

